buy_code:
매수 = True
if not (관심종목 == 1):
    매수 = False
elif {b1_start} <= 시분초 < {b1_end}:
    if {b1_cap_lo} <= 시가총액 < {b1_cap_hi}:
        if not (분당거래대금 >= {b1_min_money} and 분당거래대금 / 분당거래대금평균({b1_money_avg_win}, 1) >= {b1_money_reaccel} and 분당매수수량 >= {b1_buy_qty_min} and 누적분당매수수량({b1_cum_win}) >= {b1_cum_buy_min} and 분당매수수량 * {b1_recent_buy_mult} >= 누적분당매수수량({b1_cum_win})):
            매수 = False
    else:
        매수 = False
elif {b2_start} <= 시분초 < {b2_end}:
    if {b2_cap_lo} <= 시가총액 < {b2_cap_hi}:
        if not (현재가 > 최고현재가({b2_break_win}, 1) and 분당거래대금 >= {b2_min_money} and 분당거래대금 / 분당거래대금평균({b2_money_avg_win}, 1) >= {b2_money_reaccel} and 분당매수수량 >= {b2_buy_qty_min} and 누적분당매수수량({b2_cum_win}) >= {b2_cum_buy_min} and 분당매수수량 * {b2_recent_buy_mult} >= 누적분당매수수량({b2_cum_win})):
            매수 = False
    else:
        매수 = False
else:
    매수 = False
if 매수:
    self.Buy()

sell_code:
